package com.aerosync.model;

/**
 * Provenance of operational network records. Everything generated by
 * {@code SyntheticNetworkGenerator} is {@link #SYNTHETIC} so it can never be
 * mistaken for real flight operations.
 */
public enum DataOrigin {
    // SYNTHETIC: generated by AeroSync. IMPORTED: from an external system (the
    // data_source column names it, for example OPENSKY). MANUAL: entered by a person.
    SYNTHETIC,
    IMPORTED,
    MANUAL
}
